mapper.select:
SELECT reason FROM (
  SELECT invalidation_reason AS reason FROM check_run c WHERE project_id=#{projectId} AND document_id=#{documentId}
    AND document_revision=#{documentRevision} AND invalidation_reason IS NOT NULL
  UNION SELECT i.reason_code AS reason FROM review_invalidation i JOIN review_decision r
    ON r.tenant_id=i.tenant_id AND r.project_id=i.project_id AND r.review_id=i.review_id
    WHERE r.project_id=#{projectId} AND r.document_revision=#{documentRevision}
) reasons ORDER BY reason

 SELECT m.tenant_id,m.project_id,m.snapshot_id,m.source_id,m.source_version,m.parse_version,m.index_version,m.approval_revision,m.binding_revision
 FROM scope_member m WHERE m.project_id=#{projectId} AND m.snapshot_id=#{snapshotId}
 ORDER BY m.source_version,m.parse_version
LIMIT #{metadataLimit}
